import { useRef } from 'react';
import { useGSAP } from '@gsap/react';
import { useTranslation } from 'react-i18next';
import { gsap, ScrollTrigger, ScrollSmoother } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { useScrollStore } from '@/stores/useScrollStore';
import { navigationSections } from '@/data/navigation';

const focusRing = 'focus-visible:outline-2 focus-visible:outline-white focus-visible:outline-offset-4';

// Omit availableSections once all seven section targets are mounted.
export function Nav({ onMenuClick, menuOpen = false, availableSections }) {
  const { t } = useTranslation();
  const currentSection = useScrollStore((state) => state.currentSection);
  const reducedMotion = useReducedMotion();
  const root = useRef(null);
  const scrollTween = useRef(null);

  const { contextSafe } = useGSAP(() => {
    const bar = root.current.querySelector('nav');
    gsap.set(bar, { yPercent: 0 });
    if (reducedMotion) return () => scrollTween.current?.kill();

    const hide = gsap.to(bar, {
      yPercent: -100,
      duration: 0.35,
      ease: 'power2.out',
      paused: true,
    });

    ScrollTrigger.create({
      id: 'stellar-nav-auto-hide',
      start: 0,
      end: 'max',
      onUpdate: (self) => {
        const keepVisible = self.scroll() <= 80 || self.direction < 0 || bar.querySelector(':focus-visible');
        if (keepVisible) hide.reverse();
        else hide.play();
      },
    });

    // Keyboard users must never have to wait for an off-screen control.
    const revealOnFocus = (event) => {
      if (event.target.matches(':focus-visible')) hide.reverse().pause(0);
    };
    bar.addEventListener('focusin', revealOnFocus);
    return () => {
      scrollTween.current?.kill();
      bar.removeEventListener('focusin', revealOnFocus);
    };
  }, { scope: root, dependencies: [reducedMotion], revertOnUpdate: true });

  function navigate(event, id, available = true) {
    if (!available) {
      event.preventDefault();
      return;
    }
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    const target = document.getElementById(id);
    if (!target) return;

    contextSafe(() => {
      scrollTween.current?.kill();
      const offset = id === 'smooth-content' ? 0 : root.current.querySelector('nav').offsetHeight + 8;
      const smoother = ScrollSmoother.get();
      // Numeric coordinates avoid transformed DOM offsets inside ScrollSmoother.
      const targetY = id === 'smooth-content' ? 0 : smoother
        ? smoother.offset(target, 'top top') - offset
        : target.getBoundingClientRect().top + window.scrollY - offset;
      if (event.detail === 0) {
        const y = gsap.utils.clamp(0, ScrollTrigger.maxScroll(window), targetY);
        if (smoother) smoother.scrollTop(y);
        else window.scrollTo(0, y);
        target.setAttribute('tabindex', '-1');
        target.focus({ preventScroll: true });
        return;
      }
      scrollTween.current = gsap.to(window, {
        duration: reducedMotion ? 0 : 1,
        ease: 'power3.inOut',
        scrollTo: {
          y: gsap.utils.clamp(0, ScrollTrigger.maxScroll(window), targetY),
          autoKill: true,
        },
        overwrite: 'auto',
      });
      if (id === 'smooth-content') target.focus({ preventScroll: true });
    })();
  }

  return (
    <header ref={root}>
      <a
        href="#smooth-content"
        onClick={(event) => navigate(event, 'smooth-content')}
        className={`fixed left-[max(1.5rem,env(safe-area-inset-left))] top-[calc(0.75rem+env(safe-area-inset-top))] z-[10000] -translate-y-[150%] border border-white bg-(--bg-void) px-4 py-3 font-body text-sm text-white focus-visible:translate-y-0 ${focusRing}`}
      >
        {t('nav.skip')}
      </a>
      <nav
        aria-label={t('nav.label')}
        className="fixed inset-x-0 top-0 z-[70] flex h-[calc(4.5rem+env(safe-area-inset-top))] items-center justify-between border-b border-white/[0.08] bg-[rgba(5,5,5,0.55)] gap-3 px-[max(1.5rem,env(safe-area-inset-left),env(safe-area-inset-right))] pt-[env(safe-area-inset-top)] font-body backdrop-blur-[12px] lg:px-[max(2rem,env(safe-area-inset-left),env(safe-area-inset-right))]"
      >
        <a
          href="#smooth-content"
          aria-label={t('nav.homeLabel')}
          onClick={(event) => navigate(event, 'smooth-content')}
          className={`inline-flex min-h-11 min-w-11 shrink-0 items-center font-display text-lg font-bold tracking-tight text-white ${focusRing}`}
        >
          {t('nav.logo')}
        </a>
        <ul className="hidden items-center gap-4 lg:flex xl:gap-6">
          {navigationSections.map(({ id, key }) => {
            const available = !availableSections || availableSections.includes(id);
            const active = available && currentSection === id;
            return (
              <li key={id}>
                <a
                  href={`#${id}`}
                  aria-current={active ? 'location' : undefined}
                  aria-disabled={!available || undefined}
                  aria-describedby={!available ? 'nav-pending-sections' : undefined}
                  tabIndex={available ? undefined : -1}
                  title={!available ? t('nav.sectionPending') : undefined}
                  onClick={(event) => navigate(event, id, available)}
                  className={`inline-flex min-h-11 min-w-11 items-center whitespace-nowrap text-sm uppercase tracking-[0.08em] underline-offset-8 decoration-1 ${active ? 'text-white underline' : 'text-(--text-secondary)'} ${available ? 'hover:text-white' : 'cursor-default'} ${focusRing}`}
                >
                  {t(`nav.${key}`)}
                </a>
              </li>
            );
          })}
        </ul>
        <p id="nav-pending-sections" className="sr-only">{t('nav.sectionPending')}</p>
        <button
          type="button"
          onClick={onMenuClick}
          aria-label={t('nav.openMenu')}
          aria-expanded={menuOpen}
          aria-controls="stellar-menu"
          aria-haspopup="dialog"
          aria-disabled={!onMenuClick || undefined}
          title={!onMenuClick ? t('nav.menuPending') : undefined}
          className={`inline-flex min-h-11 min-w-11 items-center justify-center gap-2 border border-white/[0.08] px-2 text-sm uppercase tracking-[0.08em] text-white hover:border-white ${focusRing}`}
        >
          <span className="hidden lg:inline">{t('nav.menuLabel')}</span>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true" focusable="false">
            <path d="M4 8h16M4 16h16" />
          </svg>
        </button>
      </nav>
    </header>
  );
}

