import { Moon, Sun } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useThemeStore } from '@/stores/useThemeStore';

export function ThemeToggle() {
  const theme = useThemeStore((state) => state.theme);
  const toggleTheme = useThemeStore((state) => state.toggleTheme);
  const { t } = useTranslation();
  const label = t(theme === 'dark' ? 'common.theme.toLight' : 'common.theme.toDark');

  return (
    <button
      type="button"
      aria-label={label}
      title={label}
      onClick={toggleTheme}
      className="fixed right-[max(1rem,env(safe-area-inset-right))] top-[calc(5rem+env(safe-area-inset-top))] z-50 inline-flex size-11 cursor-pointer items-center justify-center rounded-md border border-secondary bg-background text-foreground pointer-events-auto hover:border-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-foreground focus-visible:ring-2 focus-visible:ring-background"
    >
      {theme === 'dark' ? <Sun className="size-5" aria-hidden="true" focusable="false" /> : <Moon className="size-5" aria-hidden="true" focusable="false" />}
    </button>
  );
}

